Tool response:
Tool: create_rsu_grant
Description: Creates a new RSU grant.
Validates that the employee belongs to the company.
Sets initial status to 'draft'.
Generates vesting schedule based on quarterly/monthly/annually frequency.
Parameters:
    {
      "type": "object",
      "properties": {
        "company_id": {
          "type": "integer",
          "title": "Company Id"
        },
        "employee_id": {
          "type": "integer",
          "title": "Employee Id"
        },
        "shares_total": {
          "type": "integer",
          "title": "Shares Total"
        },
        "vesting_start_date": {
          "type": "string",
          "title": "Vesting Start Date"
        },
        "vesting_frequency": {
          "type": "string",
          "enum": [
            "monthly",
            "quarterly",
            "annually"
          ],
          "title": "Vesting Frequency"
        },
        "vesting_period_years": {
          "type": "integer",
          "title": "Vesting Period Years"
        }
      },
      "required": [
        "company_id",
        "employee_id",
        "shares_total",
        "vesting_start_date",
        "vesting_frequency",
        "vesting_period_years"
      ]
    }

